#!/usr/bin/env node
/*
 * Regression: every safety requirement generated by a safety analysis reaches its Golden Thread (24 Oct 2026).
 *
 * FOUND (audit of 24 Oct 2026, every generator run on all eight shipped demo projects): the thread picked a
 *   requirement up only through an FHA back-reference, a trace id equal to the failure condition id, or a source
 *   id containing ":gate-indep:". 458 of 1,598 generated requirements reached a thread. Function DAL, basic
 *   event, interval, gate DAL, development / physical / CMA independence, ZSA, PRA, assumption and most human
 *   factors requirements never did. Picking an aircraft function also left out system failure conditions whose
 *   system function traces up to it (Halcyon: 0 of 18 reachable). FMEA rows sat in the fault tree column.
 * RULE (Waqas, 24 Oct 2026): only safety-generated requirements; each follows its own source back to the failure
 *   conditions it protects; STPA requirements are their own set; anything that cannot reach a failure condition
 *   is listed with the reason, never silently dropped. FMEA is verification evidence (verification side; a
 *   failure mode with no means of detection or no fault tree event is a finding). Interface requirements and the
 *   scope-wide DAL default are retired.
 * EXECUTED:
 *   [A] the REAL site/req_thread.js and the REAL _gtvBuildGraph (extracted region of fta_view_modules.js) in one
 *       vm over a hand-built project holding one requirement from EVERY generator, the expected placement of
 *       each written out independently below; the REAL model_links.js fmeaFinding.
 *   [B] in the app (Chromium, when Playwright is installed): every shipped demo, every generator run, STPA
 *       drafted, assumptions promoted; every safety-generated requirement is on a thread reachable from the
 *       function picker or on the "Not on any thread" list, and the list's Open button lands on the requirement.
 *   MUTATION PROOFS (in this suite, on altered copies of the sources): each turns [A] red.
 * Run: node tests/regression_req_thread_20261024.test.js
 */
'use strict';
const fs = require('fs'), path = require('path'), vm = require('vm'), http = require('http');
let pass = 0, fail = 0;
const check = (n, c, d) => { if (c) { pass++; console.log('  PASS  ' + n); } else { fail++; console.log('  FAIL  ' + n + (d ? ' — ' + d : '')); } };
const SITE = path.join(__dirname, '..', 'site');
const S = f => fs.readFileSync(path.join(SITE, f), 'utf8');
const RT_SRC = S('req_thread.js'), FV_SRC = S('fta_view_modules.js'), ML_SRC = S('model_links.js'), HTML = S('index.html');

// ---- the hand-built project: one requirement from every generator ---------------------------------
function project() {
    const R = (internalId, generator, sourceId, extra) => Object.assign({ internalId, id: 'R-' + internalId, text: 'Requirement ' + internalId, type: 'Safety',
        reqSource: { generator, sourceId, context: (extra && extra.ctx) || {}, fingerprint: 'x' } }, extra && extra.row);
    return {
        acFunctionsData: [{ subId: 'SF-01', subName: 'Control pitch' }, { subId: 'SF-02', subName: 'Generate thrust' }],
        acFhaData: [
            { internalId: 100, fcId: 'FC-01', subId: 'SF-01', fcDesc: 'Loss of pitch', severity: 'Catastrophic', assumptionIds: ['ASM-1'] },
            { internalId: 101, fcId: 'FC-02', subId: 'SF-02', fcDesc: 'Loss of thrust', severity: 'Hazardous' }],
        systemsData: [{ id: 'sys-fcs', name: 'Flight controls', functions: [{ funcId: 'SFN-1', funcName: 'Command elevator', traceIds: ['SF-01'] }],
            // internal id 100 on purpose: the same number as the aircraft row, so scope must decide
            fha: [{ internalId: 100, fcId: 'FC-FCS-01', subId: 'SFN-1', fcDesc: 'Elevator runaway', severity: 'Hazardous' }],
            req: [R(400, 'fha-prob', 'sys-sys-fcs:fha:prob:100')] }],
        ftaPages: [
            { id: 'pg-ac', name: 'Pitch tree', linkedFhaIds: [100], root: { id: 10, logicalId: 10, type: 'gate', gateType: 'AND', displayId: 'G-10', children: [
                { id: 11, logicalId: 11, type: 'basic', displayId: 'BE-11', children: [] },
                { id: 12, logicalId: 12, type: 'basic', displayId: 'BE-12', identity: { resourceId: 'RES-1' }, children: [] },
                { id: 13, type: 'gate', gateType: 'TRANSFER', transferOutTo: 'pg-sys', displayId: 'T-13', children: [] }] } },
            { id: 'pg-sys', name: 'Elevator tree (reached by transfer)', linkedFhaIds: [], root: { id: 20, type: 'gate', displayId: 'G-20', children: [{ id: 21, logicalId: 21, type: 'basic', displayId: 'BE-21', children: [] }] } },
            { id: 'pg-orphan', name: 'Unlinked tree', linkedFhaIds: [], root: { id: 30, type: 'gate', displayId: 'G-30', children: [{ id: 31, logicalId: 31, type: 'basic', displayId: 'BE-31', children: [] }] } }],
        zsaData: [{ internalId: 500, zoneId: 'Z-1', desc: 'Nacelle', housedFunctions: ['SF-02'] }, { internalId: 501, zoneId: 'Z-9', desc: 'Empty bay', housedFunctions: ['SF-99'] }],
        praData: [{ internalId: 600, praId: 'PRA-1', threat: 'Rotor burst', affectedZones: ['Z-1'] }, { internalId: 601, praId: 'PRA-9', threat: 'Tire burst', affectedZones: ['Z-9'] }],
        stpaData: { hazards: [{ id: 'H-1', fromFcId: 'FC-01', lossIds: ['L-1'] }, { id: 'H-2', lossIds: ['L-1'] }],
                    dispositions: { a: { status: 'assessed', hazardIds: ['H-1'] }, b: { status: 'assessed', hazardIds: ['H-2'] } } },
        acReqData: [
            R(1, 'fha-prob', 'ac:fha:prob:100'),
            R(2, 'fha-dal', 'ac:fha:dal:func:SF-01', { ctx: { subId: 'SF-01', fhaIds: [100] } }),
            R(3, 'fta-event', 'ac:fta-event:11'),
            R(4, 'fta-event', 'ac:fta-event:21'),
            R(5, 'fta-event', 'ac:fta-event:31'),
            R(6, 'fta-interval', 'ac:fta-interval-monitor:11'),
            R(7, 'fta-resource', 'ac:fta-resource:RES-1', { ctx: { resourceId: 'RES-1' } }),
            R(8, 'dalgebra', 'ac:dalgebra:pg-ac:10'),
            R(9, 'gate-indep-and', 'ac:gate-indep:pg-ac:10'),
            R(10, 'gate-indep-dev', 'ac:gate-indep-dev:pg-ac:10', { row: { compromised: true, compromiseReasons: [{ detail: 'shared supplier' }] } }),
            R(11, 'gate-indep-phys', 'ac:gate-indep-phys:pg-ac:10'),
            R(12, 'gate-indep-ccf-lib', 'ac:gate-indep-ccf-lib:pg-ac:10:LIB-1'),
            R(13, 'gate-indep-ccf-group', 'ac:gate-indep-ccf-group:pg-ac:10:GRP'),
            R(14, 'gate-indep-cma', 'ac:gate-indep-cma:pg-ac:10:900:shared-resource'),
            R(15, 'gate-indep-or', 'ac:gate-indep:pg-ac:10'),
            R(16, 'zsa-separation', 'ac:zsa:Z-1', { ctx: { zoneId: 'Z-1', housedFunctions: ['SF-02'] } }),
            R(17, 'zsa-phys', 'ac:zsa:Z-9:phys', { ctx: { zoneId: 'Z-9', housedFunctions: ['SF-99'] } }),
            R(18, 'pra-zonal', 'ac:pra:PRA-1', { row: { traceId: 'PRA-1' }, ctx: { zones: ['Z-1'], exposedFunctions: [] } }),
            R(19, 'pra-zonal', 'ac:pra:PRA-9', { row: { traceId: 'PRA-9' }, ctx: { zones: ['Z-9'], exposedFunctions: [] } }),
            R(20, 'pra-scenario', 'ac:pra:PRA-1:S1', { ctx: { scenario: 'S1', fcIds: ['101'] } }),
            R(21, 'hf-op-action', 'ac:hf-op-action:ASM-1', { ctx: { asmId: 'ASM-1', fcIds: ['FC-01'] } }),
            R(22, 'hf-op-timing', 'ac:hf-op-timing:ASM-2', { ctx: { asmId: 'ASM-2' } }),
            R(23, 'assumption', 'asm:ASM-1', { row: { linkedAsmIds: ['ASM-1'] }, ctx: { asmId: 'ASM-1' } }),
            R(24, 'assumption', 'asm:ASM-2', { row: { linkedAsmIds: ['ASM-2'] }, ctx: { asmId: 'ASM-2' } }),
            R(25, 'fcim-monitor', 'ac:fcim-monitor:P1', { ctx: { pairId: 'P1', subId: 'SF-02', fcIds: ['FC-02'] } }),
            R(26, 'usoc-info', 'ac:usoc:U-1', { ctx: { usoc: 'U-1', fc: 'FC-02', escalatesTo: 'FC-01' } }),
            { internalId: 27, id: 'R-27', text: 'STPA from H-1', type: 'Safety', uca: 'UCA-a', stpaDerived: true },
            { internalId: 28, id: 'R-28', text: 'STPA from H-2', type: 'Safety', uca: 'UCA-b', stpaDerived: true },
            R(29, 'iface-def', 'ac:iface-def:a->b:functional'),
            R(30, 'dalgebra-default', 'ac:dalgebra-default:FDAL|A'),
            R(31, 'reqif', 'ac:reqif:X'),
            { internalId: 32, id: 'R-32', text: 'Authored, not generated', type: 'Safety' }]
    };
}
// where each requirement must land: failure condition keys, 'gap', 'stpa', or 'none' (not this rule's)
const EXPECT = {
    1: ['AC:100'], 2: ['AC:100'], 3: ['AC:100'], 4: ['AC:100'], 5: 'gap', 6: ['AC:100'], 7: ['AC:100'], 8: ['AC:100'], 9: ['AC:100'],
    10: ['AC:100'], 11: ['AC:100'], 12: ['AC:100'], 13: ['AC:100'], 14: ['AC:100'], 15: ['AC:100'], 16: ['AC:101'], 17: 'gap',
    18: ['AC:101'], 19: 'gap', 20: ['AC:101'], 21: ['AC:100'], 22: 'gap', 23: ['AC:100'], 24: 'gap', 25: ['AC:101'],
    26: ['AC:100', 'AC:101'], 27: 'stpa', 28: 'stpa', 29: 'none', 30: 'none', 31: 'none', 32: 'none', 400: ['SYS:100']
};
const GEN_OF = {}; (function () { const P = project(); P.acReqData.concat(P.systemsData[0].req).forEach(r => { GEN_OF[r.internalId] = (r.reqSource && r.reqSource.generator) || (r.uca ? 'stpa' : 'authored'); }); })();

function makeCtx(P, rtSrc, fvSrc) {
    const c = { console: { log() {}, warn() {}, error() {} }, Math, JSON, String, Array, Object, Date, Number, Set, Map, RegExp, Error, isNaN, isFinite, parseFloat, parseInt };
    c.window = c; c.globalThis = c;
    Object.assign(c, P, { cmaData: [], fmeaData: [], resourcesData: [], itemsData: [] });
    vm.createContext(c);
    vm.runInContext(rtSrc, c, { filename: 'req_thread.js' });
    const a = fvSrc.indexOf('function _gtvSystemsForFc'), b = fvSrc.indexOf('function _gtvLayout');
    if (a < 0 || b < a) throw new Error('graph region not found');
    vm.runInContext(fvSrc.slice(a, b), c, { filename: 'fta_view_modules.js#graph' });
    return c;
}

// [A] returns the list of failed check names (run on the real sources and on every mutation)
function runA(rtSrc, fvSrc, mlSrc, quiet) {
    const failed = [];
    const ck = (n, cond, d) => { if (quiet) { if (!cond) failed.push(n); } else check(n, cond, d); if (!cond && !quiet) failed.push(n); };
    let c;
    try { c = makeCtx(project(), rtSrc, fvSrc); } catch (e) { ck('[A] the real sources load in a vm', false, String(e)); return failed; }
    const RT = c.SLReqThread;
    ck('[A] SLReqThread loads with its API', !!RT && typeof RT.index === 'function' && typeof RT.fcInScope === 'function' && typeof RT.renderUnthreaded === 'function');
    if (!RT) return failed;
    const idx = RT.index();
    const placed = {};
    Object.keys(idx.byFc).forEach(k => idx.byFc[k].forEach(e => { (placed[e.req.internalId] = placed[e.req.internalId] || []).push(k); }));
    const gap = new Set(idx.unthreaded.map(e => e.req.internalId)), stpa = new Set(idx.stpa.map(e => e.req.internalId));
    Object.keys(EXPECT).forEach(id => {
        const want = EXPECT[id], got = (placed[id] || []).slice().sort(), g = GEN_OF[id];
        if (want === 'gap') ck('[A] ' + g + ' requirement ' + id + ' with no failure condition is listed, with a reason', gap.has(+id) && !placed[id] && !!idx.unthreaded.find(e => e.req.internalId === +id).reason);
        else if (want === 'stpa') ck('[A] STPA requirement ' + id + ' is in the STPA set', stpa.has(+id) && !placed[id] && !gap.has(+id));
        else if (want === 'none') ck('[A] ' + g + ' requirement ' + id + ' is outside this rule (not placed, not listed)', !placed[id] && !gap.has(+id) && !stpa.has(+id));
        else ck('[A] ' + g + ' requirement ' + id + ' lands on ' + want.join(' and '), JSON.stringify(got) === JSON.stringify(want.slice().sort()), JSON.stringify(got));
    });
    // the graph the Golden Thread page draws
    const reqIn = gr => new Set(gr.nodes.filter(n => n.kind === 'req' && n.ref).map(n => String(n.ref.id)));
    const linkSet = gr => new Set(gr.links.map(l => l.s + '|' + l.t));
    const gAll = c._gtvBuildGraph({});
    const inAll = reqIn(gAll);
    const onIds = Object.keys(EXPECT).filter(id => Array.isArray(EXPECT[id]));
    ck('[A] the graph carries every placed requirement', onIds.every(id => inAll.has(id)), onIds.filter(id => !inAll.has(id)).join(','));
    ck('[A] the graph carries no listed, retired, imported or authored-only requirement', ['5', '17', '19', '22', '24', '29', '30', '31'].every(id => !inAll.has(id)));
    const L = linkSet(gAll);
    ck('[A] a basic event requirement hangs under its fault tree', L.has('fta:pg-ac|req:acReq:3'));
    ck('[A] a requirement from a tree reached only by transfer hangs under the failure condition', L.has('fc:AC:100|req:acReq:4') || [...L].some(x => /\|req:acReq:4$/.test(x) && /^fc:/.test(x)), [...L].filter(x => /req:acReq:4$/.test(x)).join(' '));
    ck('[A] a ZSA requirement hangs under its zone', L.has('cca:zsa:500|req:acReq:16'));
    ck('[A] a PRA requirement hangs under its particular risk', L.has('cca:pra:600|req:acReq:18'));
    const n10 = gAll.nodes.find(n => n.key === 'req:acReq:10');
    ck('[A] a compromised independence requirement carries its flag and reason', !!n10 && n10.flag === 'compromised' && /shared supplier/.test(n10.flagReason));
    ck('[A] every placed requirement leads to a verification status', onIds.every(id => [...L].some(x => x.startsWith('req:' + (id === '400' ? 'sysReq' : 'acReq') + ':' + id + '|vv:'))));
    // picking the aircraft function shows the system failure condition that traces up to it, and its requirement
    const g1 = c._gtvBuildGraph({ functionSubId: 'SF-01' });
    ck('[A] picking SF-01 shows the system failure condition whose system function traces to SF-01', g1.nodes.some(n => n.kind === 'fc' && n.ref && n.ref.kind === 'sysFha' && String(n.ref.id) === '100'));
    ck('[A] ... and that failure condition\'s own requirement', reqIn(g1).has('400'));
    ck('[A] picking SF-02 does not show it', !c._gtvBuildGraph({ functionSubId: 'SF-02' }).nodes.some(n => n.kind === 'fc' && n.ref && n.ref.kind === 'sysFha'));
    ck('[A] the aircraft FHA probability requirement stays on the aircraft row only (same internal id in the system)', JSON.stringify((placed[1] || [])) === '["AC:100"]' && JSON.stringify(placed[400] || []) === '["SYS:100"]');
    // STPA: H-1 came from FC-01 (its requirement rides that thread); H-2 did not (its own set)
    const gS = c._gtvBuildGraph({ functionSubId: '__stpa__' });
    ck('[A] the STPA set holds the requirement whose hazard has no failure condition, under that hazard', reqIn(gS).has('28') && linkSet(gS).has('stpa:h:H-2|req:acReq:28'));
    ck('[A] the STPA set leaves out the requirement already on its failure condition\'s thread', !reqIn(gS).has('27') && reqIn(g1).has('27'));
    ck('[A] the STPA set holds no failure condition', !gS.nodes.some(n => n.kind === 'fc'));
    // FMEA on the verification side, with findings
    try {
        const m = { console: { log() {}, warn() {}, error() {} }, Math, JSON, String, Array, Object, Date, Number, Set, Map, RegExp, Error };
        m.window = m; m.globalThis = m; vm.createContext(m);
        vm.runInContext(mlSrc, m, { filename: 'model_links.js' });
        const F = m.SLModelLinks.fmeaFinding;
        ck('[A] FMEA: a failure mode with a means of detection and a fault tree event is no finding', F({ fmeaType: 'piece-part', detection: 'BIT', beId: 901 }) === null);
        ck('[A] FMEA: no means of detection is a finding', /undetected/.test(F({ fmeaType: 'piece-part', detection: '', beId: 901 }) || '') && /undetected/.test(F({ fmeaType: 'piece-part', detection: 'None', beId: 901 }) || ''));
        ck('[A] FMEA: a piece-part failure mode with no fault tree event is a finding', /fault tree/.test(F({ fmeaType: 'piece-part', detection: 'BIT' }) || ''));
        ck('[A] FMEA rows sit on the verification side of the thread', /GT_KIND = \{ pra: 'cca', zsa: 'cca', fmea: 'vv' \}/.test(mlSrc));
    } catch (e) { ck('[A] model_links.js loads in a vm', false, String(e)); }
    return failed;
}

console.log('\n[A] the real rule and the real graph on a project with every generator');
const realFails = runA(RT_SRC, FV_SRC, ML_SRC, false);
check('[A] load order: req_thread.js loads after fta_view_modules.js and before gt_thread.js', (() => {
    const a = HTML.indexOf('src="fta_view_modules.js'), b = HTML.indexOf('src="req_thread.js'), d = HTML.indexOf('src="gt_thread.js');
    return a > 0 && b > a && d > b; })());
check('[A] the old ":gate-indep:" text match is gone from the graph builder', FV_SRC.indexOf("indexOf(':gate-indep:')") < 0);
check('[A] the Golden Thread page has the "Not on any thread" host', /id="gt-unthreaded"/.test(HTML));

console.log('\n[A] mutation proofs: each broken copy must turn the rule red');
const MUT = [
    ['the graph ignores the rule (no requirement pass)', 'fv', "(_rtIdx.byFc[domain + ':' + fha.internalId] || [])", "([])"],
    ['the old function-only scope (system failure conditions dropped from the picker)', 'fv', "if(scopeSub && !(_RT ? _RT.fcInScope(fha, domain, system, scopeSub) : subId === scopeSub)) return;", "if(scopeSub && subId !== scopeSub) return;"],
    ['events looked up by node id instead of logical id', 'rt', "('l:' + _lastPart(sid))", "('n:x' + _lastPart(sid))"],
    ['transfer-reached trees not followed up', 'rt', "if (!out.length) _arr(M.parentsOf[pid])", "if (false) _arr(M.parentsOf[pid])"],
    ['FHA rows matched without their scope', 'rt', "rows = _scopedFc(M, [c.fhaId, c.fcId, c.fhaInternalId, _lastPart(sid), r.traceId], parts[0]);", "rows = _scopedFc(M, [c.fhaId, c.fcId, c.fhaInternalId, _lastPart(sid), r.traceId], null);"],
    ['a requirement with no failure condition dropped instead of listed', 'rt', "if (!x.anchors.length) { out.unthreaded.push(base); return; }", "if (!x.anchors.length) { return; }"],
    ['always hung under the failure condition (the source element ignored)', 'fv', "if(viaKey && nodes.has(viaKey)) addLink(viaKey, rk); else addLink(fcKey, rk);", "addLink(fcKey, rk);"],
    ['STPA forced under failure conditions (no own set)', 'fv', "if(_rtIdx && (!scopeSub || scopeSub === '__stpa__')){", "if(false){"],
    ['retired generators still placed', 'rt', "if (RETIRED[g]) return { set: 'retired', anchors: [], reason: RETIRED[g] };", ""],
    ['ZSA via its zone dropped', 'rt', "if (z) via = { kind: 'cca', id: 'zsa:' + _s(z.internalId) };", ""],
    ['FMEA finding for no detection removed', 'ml', "if (!det || /^(none|n\\/a|na|-|not detected|undetected|no detection)\\b/i.test(det)) return 'No means of detection is recorded: this failure mode would go undetected.';", ""],
];
MUT.forEach(([name, which, from, to]) => {
    const srcs = { rt: RT_SRC, fv: FV_SRC, ml: ML_SRC };
    if (srcs[which].indexOf(from) < 0) { check('mutation applies: ' + name, false, 'anchor text not found'); return; }
    srcs[which] = srcs[which].replace(from, to);
    const f = runA(srcs.rt, srcs.fv, srcs.ml, true);
    check('mutation turns the suite red: ' + name, f.length > 0, f.length ? f.length + ' checks red, e.g. ' + f[0] : 'nothing went red');
});

// ---- [B] in the app, on every demo, with the real generators --------------------------------------
async function partB() {
    let pw = null;
    for (const p of ['playwright', '/home/claude/.npm-global/lib/node_modules/playwright']) { try { pw = require(p); break; } catch (_) {} }
    if (!process.env.PLAYWRIGHT_BROWSERS_PATH && fs.existsSync('/opt/pw-browsers')) process.env.PLAYWRIGHT_BROWSERS_PATH = '/opt/pw-browsers';
    if (!pw) { console.log('  note  Playwright is not installed on this machine: part [B] did not run'); return; }
    const demos = require('./lib/demo_projects_all.js').all().filter(d => d.data);
    const TYPES = { '.html': 'text/html', '.js': 'application/javascript', '.css': 'text/css', '.json': 'application/json', '.svg': 'image/svg+xml', '.png': 'image/png', '.woff2': 'font/woff2' };
    const srv = await new Promise(res => { const s = http.createServer((q, r) => { let p = decodeURIComponent(q.url.split('?')[0]); if (p.endsWith('/')) p += 'index.html'; const f = path.join(SITE, path.normalize(p)); if (!f.startsWith(SITE)) { r.writeHead(403); return r.end(); } fs.readFile(f, (e, b) => { if (e) { r.writeHead(404); return r.end(); } r.writeHead(200, { 'Content-Type': TYPES[path.extname(f)] || 'application/octet-stream' }); r.end(b); }); }).listen(0, '127.0.0.1', () => res(s)); });
    const base = 'http://127.0.0.1:' + srv.address().port + '/index.html';
    const browser = await pw.chromium.launch();
    console.log('\n[B] in the app: every shipped demo, every generator run');
    let total = 0, onThread = 0, listed = 0;
    try {
        for (const d of demos) {
            const page = await browser.newPage({ viewport: { width: 1500, height: 950 } });
            const errs = []; page.on('pageerror', e => errs.push(String(e && e.message || e)));
            page.on('dialog', dd => dd.dismiss().catch(() => {}));
            await page.goto(base);
            await page.waitForFunction(() => typeof _applyProjectData === 'function' && typeof AutoReq !== 'undefined' && window.SLReqThread, null, { timeout: 60000 });
            const r = await page.evaluate(async (data) => {
                _applyProjectData(data); await new Promise(f => setTimeout(f, 1500));
                const scopes = ['ac'].concat((systemsData || []).map(s => 'sys-' + s.id));
                for (const sc of scopes) { const m = AutoReq.generate(undefined, sc); AutoReq.applyMerge(m, { acceptNew: true, acceptUpdates: true, acceptOrphanRemoval: false }); }
                try { if (window.STPA_PANEL) STPA_PANEL.draftAllSc(); } catch (_) {}
                [{ scope: 'ac', asms: acAssumptionsData || [] }].concat((systemsData || []).map(s => ({ scope: 'sys-' + s.id, asms: s.asm || [] })))
                    .forEach(x => x.asms.forEach(a => { try { SLReqBasis.promote(x.scope, a.asmId); } catch (_) {} }));
                const vis = new Set();
                (acFunctionsData || []).map(f => f.subId).concat(['__stpa__']).forEach(sub => _gtvBuildGraph({ functionSubId: sub }).nodes.forEach(n => { if (n.kind === 'req' && n.ref) vis.add(n.ref.kind + ':' + n.ref.id); }));
                const idx = SLReqThread.index(), gap = new Set(idx.unthreaded.map(e => e.kind + ':' + e.req.internalId));
                const all = []; (acReqData || []).forEach(q => all.push(['acReq', q])); (systemsData || []).forEach(s => (s.req || []).forEach(q => all.push(['sysReq', q])));
                let total = 0, on = 0, listed = 0; const lost = [];
                all.forEach(([k, q]) => {
                    if (!SLReqThread.isSafetyGenerated(q)) return;
                    const g = SLReqThread.generatorOf(q); if (SLReqThread.RETIRED[g]) return;
                    total++; const key = k + ':' + q.internalId;
                    if (vis.has(key)) on++; else if (gap.has(key)) listed++; else if (lost.length < 3) lost.push(g + ' ' + ((q.reqSource && q.reqSource.sourceId) || q.uca));
                });
                // the page itself: the list renders the same count and its Open button lands on the requirement
                switchTab('golden-thread'); await new Promise(f => setTimeout(f, 600));
                const host = document.getElementById('gt-unthreaded');
                const shown = host && host.style.display !== 'none' ? (host.querySelectorAll('tbody tr').length) : 0;
                let opened = null;
                const btn = host && host.querySelector('.sl-rt-open');
                if (btn) { const want = btn.getAttribute('data-id'); btn.click(); await new Promise(f => setTimeout(f, 1200)); opened = { want, view: (typeof currentTab !== 'undefined' ? currentTab : '') + '|' + (document.querySelector('.view-active, [id^="view-"]:not([style*="display: none"])') || {}).id }; }
                return { total, on, listed, lost, shown, gapCount: idx.unthreaded.length, opened };
            }, d.data);
            total += r.total; onThread += r.on; listed += r.listed;
            check('[B] ' + d.key + ': every safety-generated requirement is on a reachable thread or listed (' + r.on + ' on, ' + r.listed + ' listed of ' + r.total + ')', r.on + r.listed === r.total && r.total > 0, r.lost.join('; '));
            check('[B] ' + d.key + ': the page lists exactly the requirements with no failure condition (' + r.shown + ')', r.shown === r.gapCount);
            if (r.opened) check('[B] ' + d.key + ': Open leaves the Golden Thread for the requirement', !/golden-thread/.test(r.opened.view || ''), JSON.stringify(r.opened));
            check('[B] ' + d.key + ': no page errors', errs.length === 0, errs.slice(0, 2).join(' | '));
            await page.close();
        }
        check('[B] across all demos most requirements reach a thread (' + onThread + ' of ' + total + ', ' + listed + ' listed)', total > 1000 && onThread / total > 0.9);
    } finally { await browser.close(); srv.close(); }
}
partB().catch(e => { check('[B] the browser part ran', false, String(e && e.stack || e)); }).then(() => {
    console.log('\n' + pass + ' passed, ' + fail + ' failed');
    process.exit(fail ? 1 : 0);
});
